package io.github.linker2k.myembro.engine.inkstitch

import io.github.linker2k.myembro.engine.inkstitch.lettering.InkStitchFont
import io.github.linker2k.myembro.engine.inkstitch.lettering.InkStitchLettering
import io.github.linker2k.myembro.engine.io.PesReader
import io.github.linker2k.myembro.engine.io.PesWriter
import io.github.linker2k.myembro.engine.model.Command
import java.security.MessageDigest
import kotlinx.serialization.json.*
import kotlin.math.hypot
import kotlin.test.*

/** Fixed official coordinates, not expectations generated by the implementation under test. */
class FontEquivalenceTest {
    private fun bytes(name:String)=checkNotNull(javaClass.getResourceAsStream("/inkstitch/font-equivalence/$name")).use { it.readBytes() }
    private fun JsonObject.field(name:String)=getValue(name).jsonPrimitive
    private fun JsonElement.point()=jsonArray.let { it[0].jsonPrimitive.double to it[1].jsonPrimitive.double }
    private fun distance(a:Pair<Double,Double>,b:Pair<Double,Double>)=hypot(a.first-b.first,a.second-b.second)
    private fun centered(points:List<Pair<Double,Double>>):Pair<List<Pair<Double,Double>>,Pair<Double,Double>> {
        val x=(points.minOf { it.first }+points.maxOf { it.first })/2
        val y=(points.minOf { it.second }+points.maxOf { it.second })/2
        return points.map { it.first-x to it.second-y } to (x to y)
    }
    private fun verify(id:String) {
        val oracle=Json.parseToJsonElement(bytes("oracle.json").decodeToString()).jsonObject
        val cases=oracle.getValue("cases").jsonArray
        assertTrue(cases.size in 1..10,"At most ten representative cases")
        val resources=listOf("oracle.json","font.svg","font.json","font-newline.json","PROVENANCE.md","LICENSE-GPL-3.0.txt","OFL.txt")
        assertTrue(resources.sumOf { bytes(it).size }<=1_000_000,"Oracle resource budget")
        oracle.getValue("inputs_sha256").jsonObject.forEach { (name,digest) ->
            val actual=MessageDigest.getInstance("SHA-256").digest(bytes(name)).joinToString("") { "%02x".format(it.toInt() and 255) }
            assertEquals(digest.jsonPrimitive.content,actual,"Changed frozen input: $name")
        }
        val case=cases.map { it.jsonObject }.single { it.field("id").content==id }
        val font=InkStitchFont.parse(bytes("font.svg").inputStream(),bytes(case.field("font_json").content).decodeToString())
        assertTrue(font.unsupported.isEmpty())
        val generated=InkStitchLettering.render(font,case.field("text").content,case.field("height_mm").double,forceBoundaryLocks=false)
        val pes=PesReader.read(PesWriter.write(generated,io.github.linker2k.myembro.engine.io.PesWriteSettings(inkstitchCommands=true)))
        val expected=case.getValue("needles_mm").jsonArray.map { it.point() }
        val actual=pes.stitches.filter { it.command==Command.STITCH }.map { it.x/10.0 to it.y/10.0 }
        assertEquals(expected.size,actual.size,"$id needle count")
        val (a,ac)=centered(expected);val (b,bc)=centered(actual)
        val hausdorff=maxOf(a.maxOf { p->b.minOf { q->distance(p,q) } },b.maxOf { p->a.minOf { q->distance(p,q) } })
        val criteria=oracle.getValue("criteria").jsonObject
        assertTrue(hausdorff<=criteria.field("needle_hausdorff_mm").double+1e-9,"$id Hausdorff=$hausdorff")
        val expectedControls=case.getValue("controls").jsonArray.map { it.jsonObject }
        val controls=pes.stitches.filter { it.command in setOf(Command.TRIM,Command.STOP,Command.COLOR_CHANGE) }
        assertEquals(expectedControls.size,controls.size,"$id control command count")
        var maxControlDistance=0.0
        controls.zip(expectedControls).forEach { (s,e) ->
            val command=when(s.command) { Command.TRIM->2;Command.STOP->3;Command.COLOR_CHANGE->5;else->error("control") }
            assertEquals(e.field("command").int,command,"$id ordered controls")
            val delta=distance(e.field("x_mm").double-ac.first to e.field("y_mm").double-ac.second,
                s.x/10.0-bc.first to s.y/10.0-bc.second)
            maxControlDistance=maxOf(maxControlDistance,delta)
            assertTrue(delta<=criteria.field("control_anchor_mm").double+1e-9,"$id control anchor=$delta")
        }
        assertEquals(case.getValue("thread_rgb").jsonArray.map { it.jsonPrimitive.int },pes.threads.map { it.color and 0xFFFFFF },"$id thread order")
        println("FONT_EQ PASS $id needles=${actual.size}/${expected.size} trims=${pes.trimCount} hausdorff_mm=${"%.6f".format(java.util.Locale.ROOT,hausdorff)} control_mm=${"%.6f".format(java.util.Locale.ROOT,maxControlDistance)}")
    }
    @Test fun ab4mm()=verify("fonts--testfont--004mm--AB")
    @Test fun ab10mm()=verify("fonts--testfont--010mm--AB")
    @Test fun ab20mm()=verify("fonts--testfont--020mm--AB")
    @Test fun twoLines10mm()=verify("fonts--testfont--010mm--AB-newline-BA")
}
